package com.cpf.batch.runtime;
import com.cpf.core.api.database.CpfDataSources; import org.springframework.context.annotation.*; import org.springframework.core.env.Environment; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.jdbc.datasource.DataSourceTransactionManager; import org.springframework.transaction.PlatformTransactionManager; import javax.naming.NamingException; import javax.sql.DataSource;
@Configuration public class BatDataSourceConfiguration { @Bean(name="batDataSource") @Primary DataSource batDataSource(Environment env)throws NamingException{return CpfDataSources.resolve(env,"spring.datasource.bat");} @Bean(name="batTransactionManager") @Primary PlatformTransactionManager tx(DataSource batDataSource){return new DataSourceTransactionManager(batDataSource);} @Bean(name="batJdbcTemplate") @Primary JdbcTemplate jdbc(DataSource batDataSource){return new JdbcTemplate(batDataSource);} }
